#define IFW_HOST
#define main panel_simulator_main
#include "../../firmware/src/app.c"
#undef main
#include <math.h>
#include "../../firmware/src/output_level.h"
static IFWFixedSynth alt;
static IFWFixedFxBuffers altbuf;
static int32_t pcm[512];
int main(void){
 puts("{\"kind\":\"native-note-transition-audit\",\"cases\":[");
 for(unsigned p=0;p<6;p++)for(unsigned mode=0;mode<3;mode++){
  memset(host_flash,255,sizeof host_flash);storage_load();ui_init();make_preset(&edit_patch,p);ifw_fixed_init(&synth,&edit_patch,&fx_buffers);ready=1;qread=qwrite=overflow=0;saved.wind=0;
  ifw_fixed_breath(&synth,INT32_MAX);ifw_fixed_note_on(&synth,60,INT32_MAX);
  uint32_t step=mode==0?8u:mode==1?4u:6u; /* 46, 23, 35 ms */
  int32_t last[2]={0,0};uint32_t old=60,events=0,clips=0,maxjump=0,maxevent=0;
  double energy=0;
  for(unsigned block=0;block<900;block++){
   int event=block>=180 && !((block-180)%step);
   if(mode==1 && block>=180 && (block-180)%step==step-1)midi_message(0x80,(uint8_t)old,0);
   if(event){
    alt=synth;altbuf=fx_buffers;alt.effects.buffers=&altbuf;
    int32_t predicted[2];ifw_fixed_process(&alt,predicted,1);
    uint32_t note=mode==2?60u:60u+((events*7u)%25u);
    midi_message(0x90,(uint8_t)note,110);if(mode!=1 && note!=old)midi_message(0x80,(uint8_t)old,0);old=note;events++;
    app_audio_begin();app_audio_render(pcm,256);app_audio_finish(pcm,256);
    for(unsigned ch=0;ch<2;ch++){int32_t delta=pcm[ch]-predicted[ch];uint32_t a=(uint32_t)(delta<0?-delta:delta);if(a>maxevent)maxevent=a;}
   }else app_audio(pcm,256);
   for(unsigned i=0;i<256;i++)for(unsigned ch=0;ch<2;ch++){
    int32_t v=ifw_output_sample(pcm[2*i+ch],4096),d=v-last[ch];uint32_t a=(uint32_t)(d<0?-d:d);last[ch]=v;
    if(block>=180 && a>maxjump)maxjump=a;if(v>=32767 || v<=-32767)clips++;energy+=(double)v*v;
   }
  }
  printf("%s{\"preset\":%u,\"mode\":%u,\"events\":%u,\"maxStep\":%u,\"maxEventDeltaRaw\":%u,\"clippedChannelSamples\":%u,\"rms\":%.9f}",p||mode?",":"",p,mode,events,maxjump,maxevent,clips,sqrt(energy/(900.*512))/32768.);
 }
 puts("]}");return 0;
}
